def calculate_total_turnaround_time(turnaround_times):
    total_time = 0
    for time in turnaround_times:
        total_time += time
    return total_time

def process_exploration_data(exploration_data):
    total_explorations = len(exploration_data)
    deepest_exploration = max(data["depth"] for data in exploration_data)
    unique_species = set(species for data in exploration_data for species in data["species"])

    return {
        "total_explorations": total_explorations,
        "deepest_exploration": deepest_exploration,
        "unique_species": unique_species,
    }

def find_winning_couple(scores):
    highest_score = 0
    winning_couple = ""

    for couple, score_list in scores.items():
        total_score = sum(score_list)
        if total_score > highest_score:
            highest_score = total_score
            winning_couple = couple

    return winning_couple

def analyze_transactions(transactions):
    total_income = 0.0
    total_expense = 0.0
    transactions_count = len(transactions)

    for transaction in transactions:
        amount = transaction['amount']
        transaction_type = transaction['type']

        if transaction_type == 'income':
            total_income += amount
        elif transaction_type == 'expense':
            total_expense += amount

    net_balance = total_income - total_expense

    return {
        'total_income': total_income,
        'total_expense': total_expense,
        'net_balance': net_balance,
        'transactions_count': transactions_count
    }

def total_home_goals(matches):
    total_goals = 0
    for match in matches:
        total_goals += match["home_goals"]
    return total_goals

def sandlerize_titles(movies):
    sandlerized_titles = []
    for title in movies:
        if "Sandler" in title:
            sandlerized_titles.append(title)
        else:
            new_title = title + " Sandler"
            sandlerized_titles.append(new_title)
    return sandlerized_titles

def filter_images_by_keyword(filenames, keyword):
    matching_filenames = []
    keyword = keyword.lower()
    for filename in filenames:
        if keyword in filename.lower():
            matching_filenames.append(filename)
    return matching_filenames

def can_form_triangle(sides):
    a, b, c = sorted(sides)
    return a + b > c

def find_top_team(matches):
    team_points = {}
    for match in matches:
        home_team = match['home_team']
        away_team = match['away_team']
        result = match['result']

        if home_team not in team_points:
            team_points[home_team] = 0
        if away_team not in team_points:
            team_points[away_team] = 0

        if result == 'home_win':
            team_points[home_team] += 3
        elif result == 'away_win':
            team_points[away_team] += 3
        else:
            team_points[home_team] += 1
            team_points[away_team] += 1

    sorted_teams = sorted(team_points.items(), key=lambda x: (-x[1], x[0]))
    return sorted_teams[0][0]

def calculate_percentage_change(closing_prices):
    percentage_changes = []
    for i in range(1, len(closing_prices)):
        prev_price = closing_prices[i - 1]
        curr_price = closing_prices[i]
        if prev_price == 0:
            continue
        percentage_change = ((curr_price - prev_price) / prev_price) * 100
        percentage_changes.append(percentage_change)
    if len(percentage_changes) == 0:
        return []
    else:
        percentage_changes.insert(0, None)
        return percentage_changes

def calculate_average_return(daily_returns, n):
    if n > len(daily_returns):
        n = len(daily_returns)
    last_n_returns = daily_returns[-n:]
    average_return = sum(last_n_returns) / n
    return average_return

def calculate_avg_score(student_scores):
    total_score = sum(student_scores.values())
    num_students = len(student_scores)
    avg_score = total_score / num_students
    return round(avg_score, 2)

